    for r in range(h):
      for c in range(w):
       v=grid[r][c]
       if v==0 or (r,c) in seen: continue
       st=[(r,c)]; seen.add((r,c)); pts=[]
       while st:
        y,x=st.pop(); pts.append((y,x))
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         yy,xx=y+dy,x+dx
         if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==v:
          seen.add((yy,xx)); st.append((yy,xx))
       comps.append((v,pts))
    out=[[0]*w for _ in range(h)]
    # Slide components in left half upward and right half downward, stopping before collision.
    for side in (0,1):
      group=[(v,p) for v,p in comps if ((min(x for y,x in p)+max(x for y,x in p))/2 >= w/2) == bool(side)]
      group.sort(key=lambda z:min(y for y,x in z[1]))
      for v,pts in group:
       dr=-min(y for y,x in pts) if side==0 else h-1-max(y for y,x in pts)
       while True:
        moved=[(y+dr,x) for y,x in pts]
        if all(0<=y<h and out[y][x]==0 for y,x in moved): break
        dr += 1 if side==0 else -1
       for y,x in moved: out[y][x]=v
    return out

def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       v=grid[r][c]
       if not v or (r,c) in seen: continue
       st=[(r,c)]; seen.add((r,c)); pts=[]
       while st:
        y,x=st.pop(); pts.append((y,x))
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
         yy,xx=y+dy,x+dx
         if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==v:
          seen.add((yy,xx)); st.append((yy,xx))
       comps.append((v,pts))
    out=[[0]*w for _ in range(h)]
    # Each object moves vertically to the edge of its original half: upper objects rise,
    # lower objects fall. Resolve any overlaps by placing nearest-to-edge objects first.
    for upper in (True,False):
      group=[(v,p) for v,p in comps if ((min(y for y,x in p)+max(y for y,x in p))/2 < h/2) == upper]
      group.sort(key=lambda z:min(y for y,x in z[1]) if upper else -max(y for y,x in z[1]))
      for v,p in group:
       a=min(y for y,x in p); b=max(y for y,x in p)
       d=-a if upper else h-1-b; step=1 if upper else -1
       while True:
        q=[(y+d,x) for y,x in p]
        if all(0<=y<h and out[y][x]==0 for y,x in q): break
        d+=step
       for y,x in q: out[y][x]=v
    return out
